const rows = $input.all();
const topicId = rows[0]?.json.article_id || $('Merge Humanized With Topic').first().json.id;
return [{ json: { id: topicId, images_done: rows.length } }];

const prompts = $('Parse Image Prompts').all();
const files = $input.all();
return files.map((f, i) => ({ json: {
  article_id: prompts[i].json.article_id,
  scene: prompts[i].json.scene,
  image_prompt: prompts[i].json.image_prompt,
  file_url: f.json.webViewLink,
  status: 'done'
} }));

const items = $input.all();
const out = [];
for (const item of items) {
  const img = item.json.images?.[0] || item.json.data?.[0];
  if (!img) continue;
  const b64 = (img.b64_json || img.url || '').replace(/^data:image\/\w+;base64,/, '');
  const buffer = Buffer.from(b64, 'base64');
  out.push({
    json: item.json,
    binary: { data: await this.helpers.prepareBinaryData(buffer, `${item.json.article_id}_${item.json.image_index}.png`, 'image/png') }
  });
}
return out;

