const raw = $input.first().json.output;
const clean = String(raw).replace(/```json|```/g, '').trim();
const topics = JSON.parse(clean);
return topics.map(t => ({ json: t }));

// Stop-words to ignore when comparing similarity.
// NOTE: kept in Russian on purpose — this filters Russian-language topic titles
// (the channel publishes in Russian), so the stopword list and the regex charset
// below must stay Russian for the matching to work correctly.
const stopWords = new Set([
  'как', 'что', 'это', 'она', 'он', 'её', 'их', 'для', 'при', 'или',
  'на', 'из', 'до', 'по', 'не', 'но', 'то', 'а', 'и', 'в', 'с', 'у',
  'женщин', 'женщина', 'женщины', 'история', 'который', 'которые', 'которая'
]);

function getKeywords(text) {
  return text
    .toLowerCase()
    .replace(/[^а-яё\s]/gi, ' ')
    .split(/\s+/)
    .filter(w => w.length > 3 && !stopWords.has(w));
}

function similarity(words1, words2) {
  const set1 = new Set(words1);
  const set2 = new Set(words2);
  const intersection = [...set1].filter(w => set2.has(w));
  const union = new Set([...set1, ...set2]);
  return union.size ? intersection.length / union.size : 0;
}

// Pull the already-used topics from the upstream node
const excludeRaw = $('Build Exclude List').first().json.excludeList;
const existingTitles = excludeRaw === 'no data' ? [] : excludeRaw.split('; ').filter(Boolean);
const existingKeywords = existingTitles.map(getKeywords);

const items = $input.all();
const seenInThisBatch = [];
const result = [];

for (const item of items) {
  const title = item.json.title || '';
  const kw = getKeywords(title);

  // Compare against both already-published/queued topics and topics from this same batch
  const isDuplicate = [...existingKeywords, ...seenInThisBatch].some(
    existing => similarity(kw, existing) > 0.4
  );

  if (!isDuplicate) {
    seenInThisBatch.push(kw);
    result.push(item);
  }
}

return result;

const members = $json.query.categorymembers.map(m => m.title);
const excludeRaw = $('Build Exclude List').first().json.excludeList;
const excluded = excludeRaw === 'no data' ? [] : excludeRaw.toLowerCase();

const fresh = members.filter(name => !excluded.includes(name.toLowerCase().split(' ')[0]));
const shuffled = fresh.sort(() => Math.random() - 0.5).slice(0, 15);

return [{ json: { names: shuffled.join('; ') } }];
